    // The function modules must be marked and the codeword bits must be drawn
    // before masking. Due to the arithmetic of XOR, calling applyMask() with
    // the same mask value a second time will undo the mask. A final well-formed
    // QR Code needs exactly one (not zero, two, etc.) mask applied.
    applyMask(mask) {
        if (mask < 0 || mask > 7) throw new RangeError('Mask value out of range');
        for(let y = 0; y < this.size; y++)for(let x = 0; x < this.size; x++){
            let invert;
            switch(mask){
                case 0:
                    invert = (x + y) % 2 == 0;
                    break;
                case 1:
                    invert = y % 2 == 0;
                    break;
                case 2:
                    invert = x % 3 == 0;
                    break;
                case 3:
                    invert = (x + y) % 3 == 0;
                    break;
                case 4:
                    invert = (Math.floor(x / 3) + Math.floor(y / 2)) % 2 == 0;
                    break;
                case 5:
                    invert = x * y % 2 + x * y % 3 == 0;
                    break;
                case 6:
                    invert = (x * y % 2 + x * y % 3) % 2 == 0;
                    break;
                case 7:
                    invert = ((x + y) % 2 + x * y % 3) % 2 == 0;
                    break;
                default:
                    throw new Error('Unreachable');
            }
            if (!this.isFunction[y][x] && invert) this.modules[y][x] = !this.modules[y][x];
        }
    }
    // Calculates and returns the penalty score based on state of this QR Code's current modules.
    // This is used by the automatic mask choice algorithm to find the mask pattern that yields the lowest score.
    getPenaltyScore() {
        let result = 0;
        // Adjacent modules in row having same color, and finder-like patterns
        for(let y = 0; y < this.size; y++){
            let runColor = false;
            let runX = 0;
            const runHistory = [
                0,
                0,
                0,
                0,
                0,
                0,
                0
            ];
            for(let x = 0; x < this.size; x++)if (this.modules[y][x] == runColor) {
                runX++;
                if (runX == 5) result += QrCode.PENALTY_N1;
                else if (runX > 5) result++;
            } else {
                this.finderPenaltyAddHistory(runX, runHistory);
                if (!runColor) result += this.finderPenaltyCountPatterns(runHistory) * QrCode.PENALTY_N3;
                runColor = this.modules[y][x];
                runX = 1;
            }
            result += this.finderPenaltyTerminateAndCount(runColor, runX, runHistory) * QrCode.PENALTY_N3;
        }
        // Adjacent modules in column having same color, and finder-like patterns
        for(let x = 0; x < this.size; x++){
            let runColor = false;
            let runY = 0;
            const runHistory = [
                0,
                0,
                0,
                0,
                0,
                0,
                0
            ];
            for(let y = 0; y < this.size; y++)if (this.modules[y][x] == runColor) {
                runY++;
                if (runY == 5) result += QrCode.PENALTY_N1;
                else if (runY > 5) result++;
            } else {
                this.finderPenaltyAddHistory(runY, runHistory);
                if (!runColor) result += this.finderPenaltyCountPatterns(runHistory) * QrCode.PENALTY_N3;
                runColor = this.modules[y][x];
                runY = 1;
            }
            result += this.finderPenaltyTerminateAndCount(runColor, runY, runHistory) * QrCode.PENALTY_N3;
        }
        // 2*2 blocks of modules having same color
        for(let y = 0; y < this.size - 1; y++)for(let x = 0; x < this.size - 1; x++){
            const color = this.modules[y][x];
            if (color == this.modules[y][x + 1] && color == this.modules[y + 1][x] && color == this.modules[y + 1][x + 1]) result += QrCode.PENALTY_N2;
        }
        // Balance of dark and light modules
        let dark = 0;
        for (const row of this.modules)dark = row.reduce((sum, color)=>sum + (color ? 1 : 0), dark);
        const total = this.size * this.size; // Note that size is odd, so dark/total != 1/2
        // Compute the smallest numbereger k >= 0 such that (45-5k)% <= dark/total <= (55+5k)%
        const k = Math.ceil(Math.abs(dark * 20 - total * 10) / total) - 1;
        assert(0 <= k && k <= 9);
        result += k * QrCode.PENALTY_N4;
        assert(0 <= result && result <= 2568888); // Non-tight upper bound based on default values of PENALTY_N1, ..., N4
        return result;
    }
    /*-- Private helper functions --*/ // Returns an ascending list of positions of alignment patterns for this version number.
